#include <cuda_fp16.h>
#include <cstdio>

__device__ __forceinline__ void cp16(void* smem, const void* gmem) {
    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
}
__device__ __forceinline__ void commit() { asm volatile("cp.async.commit_group;\n"); }
template<int N> __device__ __forceinline__ void wait() { asm volatile("cp.async.wait_group %0;\n" :: "n"(N)); }

// Each block: 4 tiles of 128 halfs. Load src[t] into buf[t&1] with prefetch-ahead,
// then sum-copy to dst to verify ordering.
__global__ void tk(const __half* src, float* dst, int ntiles) {
    __shared__ __half buf[2][128];
    const int t = threadIdx.x;  // 128 threads
    // prologue: tile 0
    cp16(&buf[0][t], src + t);
    commit();
    for (int nt = 0; nt < ntiles; ++nt) {
        if (nt + 1 < ntiles) {
            cp16(&buf[(nt + 1) & 1][t], src + (nt + 1) * 128 + t);
            commit();
            wait<1>();
        } else {
            wait<0>();
        }
        __syncthreads();
        // verify tile nt equals expected: accumulate into dst
        float v = (float)buf[nt & 1][t] - (float)(nt * 1.0f) * 0.5f;
        // also write it back so we can check
        dst[nt * 128 + t] = (float)buf[nt & 1][t];
        __syncthreads();
    }
}

int main() {
    const int ntiles = 8, N = ntiles * 128;
    __half* src; cudaMalloc(&src, N * 2);
    float* dst; cudaMalloc(&dst, N * 4);
    std::vector<__half> hsrc(N);
    for (int i = 0; i < N; ++i) hsrc[i] = __float2half(i * 0.5f);
    cudaMemcpy(src, hsrc.data(), N * 2, cudaMemcpyHostToDevice);
    tk<<<1, 128>>>(src, dst, ntiles);
    cudaDeviceSynchronize();
    std::vector<float> hdst(N);
    cudaMemcpy(dst, hdst.data()? (void*)0 : (void*)0, 0, cudaMemcpyDeviceToHost);
    cudaMemcpy(dst, hdst.data(), 0, cudaMemcpyDeviceToHost);
    cudaMemcpy(&hdst[0], dst, N * 4, cudaMemcpyDeviceToHost);
    int bad = 0;
    for (int i = 0; i < N; ++i) {
        float exp = i * 0.5f;
        if (hdst[i] != exp) { if (bad < 10) printf("i=%d got %f exp %f\n", i, hdst[i], exp); ++bad; }
    }
    printf("bad=%d\n", bad);
    return 0;
}

